#!/usr/bin/env python
"""Calibration and selective prediction from the saved test predictions: risk-coverage (accuracy when the least confident
questions are abstained), AURC, ECE, for Opsis-S, Opsis-V and their probability fusion (3 seed pairs), and
the same on PanNuke for seen organs (fold split, final_fov_s<k>) against unseen organs (organ split, final_fov_organ_s0): does
confidence flag the unseen organs and does abstention recover accuracy there.    python scripts/75_selective.py [--out results/collected/RESULTS_selective.md]"""
import argparse, json, os
import numpy as np, pandas as pd
from opsis import paths
ap = argparse.ArgumentParser(); ap.add_argument("--out", default=None); a = ap.parse_args(); R = paths.RUNS; K = 32
def load(run, split="test"):
    f = f"{R}/{run}/predictions_{split}.parquet"
    if not os.path.exists(f): return None
    P = pd.read_parquet(f)
    def pad(p): v = np.asarray(p, float); o = np.zeros(K); o[:len(v)] = v[:K]; return o / max(o.sum(), 1e-9)
    P["probs"] = P["probs"].map(pad); return P[["qid", "fov", "op", "family", "answer", "probs"]]
def curves(P, probs=None):
    p = np.stack(P.probs.to_list()) if probs is None else probs; y = P.answer.to_numpy(); conf = p.max(1); correct = (p.argmax(1) == y)
    order = np.argsort(-conf); c = correct[order]; cov = np.arange(1, len(c) + 1) / len(c); risk = 1 - np.cumsum(c) / np.arange(1, len(c) + 1)
    at = {f"acc@{int(q*100)}": float(1 - risk[int(q * len(c)) - 1]) for q in (1.0, 0.9, 0.8, 0.7, 0.5)}
    bins = np.linspace(0, 1, 11); idx = np.clip(np.digitize(conf, bins) - 1, 0, 9); ece = float(sum(abs(correct[idx == b].mean() - conf[idx == b].mean()) * (idx == b).mean() for b in range(10) if (idx == b).any()))
    return dict(n=len(c), acc=float(correct.mean()), aurc=float(np.trapezoid(risk, cov)), ece=ece, mean_conf=float(conf.mean()), **at)
rows = []
for k in range(3):
    S, V = load(f"final_fov_s{k}"), load(f"final_vlm_s{k}")
    if S is None or V is None: continue
    M = S.merge(V[["qid", "probs"]].rename(columns={"probs": "pv"}), on="qid"); ps = np.stack(M.probs.to_list()); pv = np.stack(M.pv.to_list()); g = np.sqrt(ps * pv); g /= g.sum(1, keepdims=True)
    for name, pr in (("structured", ps), ("VLM", pv), ("fusion (geometric mean)", g)): rows.append(dict(set="NuCLS test", seed=k, model=name, **curves(M, pr)))
T = pd.DataFrame(rows); G = T.groupby(["set", "model"], sort=False).mean(numeric_only=True).drop(columns="seed").reset_index(); print(G.round(3).to_string(index=False))
# PanNuke: seen organs (fold split test) vs unseen organs (organ split test), Opsis-S
seen = load("final_fov_s0", "test_extra"); unseen = load("final_fov_organ_s0", "test_extra"); O = []
if seen is not None and unseen is not None:
    for name, P in (("PanNuke, seen organs (fold split)", seen), ("PanNuke, unseen organs (organ split)", unseen)): O.append(dict(set=name, model="structured", **curves(P)))
    # per FOV mean confidence as an out of distribution score
    cs = seen.assign(conf=seen.probs.map(np.max)).groupby("fov").conf.mean(); cu = unseen.assign(conf=unseen.probs.map(np.max)).groupby("fov").conf.mean()
    from sklearn.metrics import roc_auc_score
    ood = float(roc_auc_score(np.r_[np.zeros(len(cs)), np.ones(len(cu))], -np.r_[cs.to_numpy(), cu.to_numpy()]))
    O.append(dict(set="FOV level: unseen organ detection from mean confidence (AUROC, lower confidence = unseen)", model="structured", auroc=ood, n=len(cs) + len(cu)))
    OD = pd.DataFrame(O); print(OD.round(3).to_string(index=False))
if a.out:
    md = ["# Calibration and selective prediction (generated by scripts/75_selective.py)", "", "acc@q: accuracy on the q percent most confident questions (the rest abstained). AURC: area under the risk-coverage curve (lower is better). ECE: 10 bin expected calibration error. NuCLS test, mean over 3 seeds (seed pairs for the fusion).", "",
          "| " + " | ".join(G.columns) + " |", "|" + "---|" * len(G.columns), *("| " + " | ".join(f"{x:.3f}" if isinstance(x, float) else str(x) for x in r) + " |" for r in G.itertuples(index=False))]
    if O: md += ["", "## Unseen organs (PanNuke), structured tier", "", "| " + " | ".join(OD.columns) + " |", "|" + "---|" * len(OD.columns), *("| " + " | ".join("" if (isinstance(x, float) and np.isnan(x)) else (f"{x:.3f}" if isinstance(x, float) else str(x)) for x in r) + " |" for r in OD.itertuples(index=False))]
    open(a.out, "w").write("\n".join(md) + "\n"); print("written", a.out)
